module Adder32(
    input [31:0] A,
    input [31:0] B,
    output [31:0] Sum,
    output CarryOut
);
    assign {CarryOut, Sum} = A + B;
endmodule

testbench:
`timescale 1ns/1ps

module Adder32_tb;

    // Testbench signals (combinational circuit)
    reg [31:0] A;
    reg [31:0] B;
    wire CarryOut;
    wire [31:0] Sum;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    Adder32 dut (
        .A(A),
        .B(B),
        .CarryOut(CarryOut),
        .Sum(Sum)
    );
    task testcase001;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Zero Addition (0 + 0)", test_num);
        A = 32'h00000000;
        B = 32'h00000000;
        #1;

        check_outputs(1'b0, 32'h00000000);
    end
        endtask

    task testcase002;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Basic Addition (Small Values)", test_num);
        A = 32'h00000005;
        B = 32'h0000000A;
        #1;

        check_outputs(1'b0, 32'h0000000F);
    end
        endtask

    task testcase003;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: No Overflow Boundary (7FFFFFFF + 1)", test_num);
        A = 32'h7FFFFFFF;
        B = 32'h00000001;
        #1;

        check_outputs(1'b0, 32'h80000000);
    end
        endtask

    task testcase004;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Overflow Occurring (FFFFFFFF + 1)", test_num);
        A = 32'hFFFFFFFF;
        B = 32'h00000001;
        #1;

        check_outputs(1'b1, 32'h00000000);
    end
        endtask

    task testcase005;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Max Possible Values (FFFFFFFF + FFFFFFFF)", test_num);
        A = 32'hFFFFFFFF;
        B = 32'hFFFFFFFF;
        #1;

        check_outputs(1'b1, 32'hFFFFFFFE);
    end
        endtask

    task testcase006;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Alternating Bit Patterns", test_num);
        A = 32'hAAAAAAAA;
        B = 32'h55555555;
        #1;

        check_outputs(1'b0, 32'hFFFFFFFF);
    end
        endtask

    task testcase007;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: High Bit Carry (80000000 + 80000000)", test_num);
        A = 32'h80000000;
        B = 32'h80000000;
        #1;

        check_outputs(1'b1, 32'h00000000);
    end
        endtask

    task testcase008;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Random Pattern Addition", test_num);
        A = 32'h12345678;
        B = 32'h87654321;
        #1;

        check_outputs(1'b0, 32'h99999999);
    end
        endtask

    task testcase009;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Carry Propagate Test (FFFF0000 + 00010000)", test_num);
        A = 32'hFFFF0000;
        B = 32'h00010000;
        #1;

        check_outputs(1'b1, 32'h00000000);
    end
        endtask

    task testcase010;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Sum to Max Signed (3FFFFFFF + 40000000)", test_num);
        A = 32'h3FFFFFFF;
        B = 32'h40000000;
        #1;

        check_outputs(1'b0, 32'h7FFFFFFF);
    end
        endtask

    // Test stimulus
