module chebyshev_filter (
    input clk,
    input reset,
    input signed [3:0] x, // 4-bit input signal
    output reg signed [3:0] y // 4-bit output signal
);
    reg signed [3:0] y1, y2, y3; // previous outputs

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 4'b0;
            y1 <= 4'b0;
            y2 <= 4'b0;
            y3 <= 4'b0;
        end else begin
