module pwm_generator (
    input wire clk,
    input wire reset,
    input wire [7:0] duty_cycle, // 0 to 255
    output reg pwm_output
);

reg [7:0] counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 8'b0;
        pwm_output <= 1'b0;
    end else begin
        counter <= counter + 1;
        if (counter < duty_cycle) begin
            pwm_output <= 1'b1;
        end else begin
            pwm_output <= 1'b0;
        end
    end
end

endmodule

