module temp_shutdown(  
    input clk,  
    input reset,  
    input [7:0] temperature,  
    output reg shutdown  
);  
    reg [1:0] over_temp_counter;  
    parameter THRESHOLD = 8'd75;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shutdown <= 0;  
            over_temp_counter <= 0;  
        end else begin  
            if (temperature > THRESHOLD) begin  
                if (over_temp_counter < 2) begin  
                    over_temp_counter <= over_temp_counter + 1;  
                end  
            end else begin  
                over_temp_counter <= 0;  
            end  
            if (over_temp_counter == 2) begin  
                shutdown <= 1;  
            end  
        end  
    end  
endmodule

