module fractional_n_pll(
    input wire clk_in,
    input wire reset,
    input wire [7:0] frac_div,
    output reg clk_out
);
    reg [15:0] phase_accumulator;
    reg [15:0] vco_output;
    reg [15:0] loop_filter_output;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            phase_accumulator <= 0;
            vco_output <= 0;
            loop_filter_output <= 0;
            clk_out <= 0;
        end else begin
            phase_accumulator <= phase_accumulator + frac_div;
            loop_filter_output <= (loop_filter_output + phase_accumulator) >> 1; // Simple low-pass filter
            vco_output <= loop_filter_output; // VCO output
            clk_out <= vco_output[15]; // Output bit
        end
    end
endmodule

