module PLL_2x (
    input wire clk_in,
    input wire reset,
    output reg clk_out
);
    reg [1:0] phase;
    reg clk_vco;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            phase <= 2'b00;
            clk_vco <= 1'b0;
        end else begin
            // Phase detector logic
            phase <= phase + 1'b1;

            // Voltage-controlled oscillator (VCO) simulation
            if (phase == 2'b01) 
                clk_vco <= ~clk_vco; // Toggle for 2x frequency

            // Output clock generation
            clk_out <= clk_vco;
        end
    end
endmodule

