module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire start_tx,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600; // Example baud rate
    reg [3:0] bit_count;
    reg [15:0] baud_counter;
    reg [3:0] state;

    localparam IDLE = 4'b0000,
               START_BIT = 4'b0001,
               DATA_BITS = 4'b0010,
               STOP_BIT = 4'b0011;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1;
            busy <= 0;
            bit_count <= 0;
            baud_counter <= 0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    busy <= 0;
                    if (start_tx) begin
                        busy <= 1;
                        baud_counter <= 0;
                        bit_count <= 0;
                        tx <= 0; // Start bit
                        state <= START_BIT;
                    end
                end
                START_BIT: begin
                    if (baud_counter == (BAUD_RATE / 115200)) begin // Adjust for baud rate
                        baud_counter <= 0;
                        state <= DATA_BITS;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                DATA_BITS: begin
                    if (baud_counter == (BAUD_RATE / 115200)) begin
                        baud_counter <= 0;
                        tx <= data_in[bit_count]; // Send data bits
                        bit_count <= bit_count + 1;
                        if (bit_count == 7) begin
                            state <= STOP_BIT;
                        end
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                STOP_BIT: begin
                    if (baud_counter == (BAUD_RATE / 115200)) begin
                        baud_counter <= 0;
                        tx <= 1; // Stop bit
                        busy <= 0;
                        state <= IDLE;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
            endcase
        end
    end
endmodule

