module VCO (
    input wire clk,
    input wire reset,
    input wire [7:0] control_voltage, // 0-255 mapped to 0V-3.3V
    output reg vco_output
);
    reg [31:0] counter;
    reg [31:0] frequency;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 32'b0;
            vco_output <= 1'b0;
            frequency <= 32'd10000; // Start at maximum frequency
        end else begin
            // Map control_voltage (0-255) to frequency (1Hz to 10kHz)
            frequency <= 32'd10000 - (control_voltage * 390); // Simple linear mapping
            counter <= counter + 1;
            if (counter >= (50000000 / frequency)) begin // Assuming clk is 50MHz
                vco_output <= ~vco_output; // Toggle output
                counter <= 32'b0;
            end
        end
    end
endmodule

