module uart_tx #(parameter BAUD_RATE = 9600, CLOCK_FREQ = 50000000) (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] data_in,  
    input wire send,  
    output reg tx,  
    output reg busy  
);  
    localparam IDLE = 2'b00,  
               START = 2'b01,  
               DATA = 2'b10,  
               STOP = 2'b11;  

    reg [1:0] state;  
    reg [3:0] bit_index;  
    reg [7:0] buffer;  
    reg [19:0] clk_div;  
    reg [3:0] clk_counter;  
    parameter CLK_DIV_VALUE = CLOCK_FREQ / (BAUD_RATE * 16);  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            tx <= 1;  
            busy <= 0;  
            clk_div <= 0;  
            bit_index <= 0;  
            buffer <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send && !busy) begin  
                        buffer <= data_in;  
                        state <= START;  
                        busy <= 1;  
                    end  
                end  
                START: begin  
                    tx <= 0; // Start bit  
                    state <= DATA;  
                    clk_div <= 0;  
                end  
                DATA: begin  
                    if (clk_div == CLK_DIV_VALUE) begin  
                        clk_div <= 0;  
                        tx <= buffer[bit_index];  
                        if (bit_index == 7) begin  
                            bit_index <= 0;  
                            state <= STOP;  
                        end else begin  
                            bit_index <= bit_index + 1;  
                        end  
                    end else begin  
                        clk_div <= clk_div + 1;  
                    end  
                end  
                STOP: begin  
                    if (clk_div == CLK_DIV_VALUE) begin  
                        tx <= 1; // Stop bit  
                        busy <= 0;  
                        state <= IDLE;  
                    end else begin  
                        clk_div <= clk_div + 1;  
                    end  
                end  
            endcase  
        end  
    end  
