module aes_8bit (
    input wire [7:0] plaintext,
    input wire [127:0] key,
    input wire clk,
    input wire reset,
    output reg [7:0] ciphertext
);
    // Internal registers for key expansion and state
    reg [127:0] round_key;
    reg [7:0] state;

    // Key expansion (simplified for 8-bit AES)
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            round_key <= 128'b0;
            ciphertext <= 8'b0;
        end else begin
            // Simple key expansion logic (for demo purposes)
            round_key <= key; // In a real AES, this would involve more steps

            // Initial state assignment
            state <= plaintext ^ round_key[7:0]; // Simplified XOR operation

            // SubBytes step (simple substitution)
            state <= {state[6:0], state[7]}; // Example substitution (rotate left)

            // Output the ciphertext
            ciphertext <= state ^ round_key[15:8]; // Simplified round transformation
        end
    end
endmodule

