module sliding_window_controller(  
    input wire clk,  
    input wire reset,  
    input wire send,  
    input wire receive,  
    output reg [3:0] current_window_size,  
    output reg sending_done  
);  
    parameter MAX_WINDOW_SIZE = 4;  
    reg [3:0] sent_frames;  
    reg [3:0] acked_frames;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            current_window_size <= 0;  
            sent_frames <= 0;  
            acked_frames <= 0;  
            sending_done <= 0;  
        end else begin  
            if (send && current_window_size < MAX_WINDOW_SIZE) begin  
                sent_frames <= sent_frames + 1;  
                current_window_size <= current_window_size + 1;  
                sending_done <= 0;  
            end  
            if (receive) begin  
                if (acked_frames < sent_frames) begin  
                    acked_frames <= acked_frames + 1;  
                    current_window_size <= current_window_size - 1;  
                end  
                sending_done <= 1;  
            end  
        end  
    end  
endmodule

module uart_controller (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] data_in,
    output reg tx
);
    reg [3:0] state;
    reg [3:0] bit_counter;
    reg [7:0] data_reg;

    localparam IDLE = 4'b0000,
               START_BIT = 4'b0001,
               DATA_BITS = 4'b0010,
               STOP_BIT = 4'b0011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1'b1; // Idle state of UART is high
            bit_counter <= 4'b0000;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        data_reg <= data_in;
                        state <= START_BIT;
                        bit_counter <= 4'b0000;
                        tx <= 1'b0; // Start bit
                    end
                end
                START_BIT: begin
                    state <= DATA_BITS;
                end
                DATA_BITS: begin
                    if (bit_counter < 8) begin
                        tx <= data_reg[bit_counter];
                        bit_counter <= bit_counter + 1;
                    end else begin
                        state <= STOP_BIT;
                    end
                end
                STOP_BIT: begin
                    tx <= 1'b1; // Stop bit
                    state <= IDLE; // Return to idle
                end
            endcase
        end
    end
endmodule

