module serializer_16bit (  
    input wire clk,  
    input wire reset,  
    input wire [15:0] parallel_in,  
    input wire start,  
    output reg serial_out  
);  
    reg [3:0] bit_counter;  
    reg [15:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_counter <= 0;  
            serial_out <= 0;  
            shift_reg <= 0;  
        end else if (start) begin  
            if (bit_counter < 16) begin  
                serial_out <= shift_reg[15];  
                shift_reg <= shift_reg << 1;  
                bit_counter <= bit_counter + 1;  
            end else begin  
                bit_counter <= 0;  
                shift_reg <= parallel_in;  
            end  
        end  
    end  
endmodule

module carrier_recovery(input clk, input reset, input modulated_signal, output reg carrier_signal);  
    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            carrier_signal <= 0;  
        end else begin  
            counter <= counter + 1;  
            if (counter == 4'd15) begin  
                carrier_signal <= modulated_signal;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

