module dma_controller (
    input clk,
    input reset,
    input [3:0] req,       // Request signals for 4 channels
    input [3:0] enable,    // Enable signals for 4 channels
    output reg [7:0] address, // Memory address output
    output reg [1:0] active_channel // Active channel indicator
);

    reg [1:0] current_channel;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_channel <= 2'b00;
            address <= 8'b00000000;
            active_channel <= 2'b00;
        end else begin
            if (req[current_channel] && enable[current_channel]) begin
                address <= {6'b000000, current_channel}; // Simple address mapping
                active_channel <= current_channel;
            end

            // Round-robin channel selection
            current_channel <= (current_channel + 1) % 4;
        end
    end
endmodule

