module reset_controller (
    input wire clk,
    input wire reset_n,
    output reg rst_out
);
    reg [2:0] count;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            rst_out <= 0;
            count <= 0;
        end else if (count < 5) begin
            count <= count + 1;
            rst_out <= 0;
        end else begin
            rst_out <= 1;
        end
    end
endmodule

